CREATE OR REPLACE FUNCTION public.account_mfa_allowed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.workspace_sessions WHERE id::text=auth.jwt()->>'session_id' AND user_id=auth.uid() AND revoked_at IS NOT NULL) AND (coalesce(auth.jwt()->>'aal','aal1')='aal2' OR NOT EXISTS(SELECT 1 FROM auth.mfa_factors WHERE user_id=auth.uid() AND status='verified')); $$;
CREATE OR REPLACE FUNCTION public.notify_new_workspace_device() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.workspace_sessions WHERE user_id=NEW.user_id AND id<>NEW.id) THEN INSERT INTO public.notifications(user_id,title,body,kind,event_key) VALUES(NEW.user_id,'New workspace session',NEW.device||' was observed. If this was not you, sign out other sessions in Settings.','security','session:'||NEW.id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER new_device_notification AFTER INSERT ON public.workspace_sessions FOR EACH ROW EXECUTE FUNCTION public.notify_new_workspace_device();